// --- CÓDIGO PARA VERIFICAR SE UM CONTACTO EXISTE E RETORNAR O SOURCE_ID ---

// 1. Pega os dados de entrada.
const listaCompleta = $input.first().json.payload;
const jidParaBuscar = $items('confirma endereço')[0].json.telefone_real;

// 2. Usa o método .find() para procurar na lista.
const contatoEncontrado = listaCompleta.find(contacto => {

  const phone = contacto.phone_number?.replace(/\D/g, "");
  const source = contacto.contact_inboxes?.[0]?.source_id?.replace(/\D/g, "");
  const jid = jidParaBuscar.replace(/\D/g, "");

  return phone === jid || source === jid;
});

// 3. Define as variáveis de saída com base no resultado da busca.
let contatoExiste = false;
let sourceId = null;
let contactId = null;

if (contatoEncontrado) {
contatoExiste = true;
contactId = contatoEncontrado.id;

// Verifica se a propriedade 'contact_inboxes' existe e não está vazia.
if (contatoEncontrado.contact_inboxes && contatoEncontrado.contact_inboxes.length > 0) {
// Pega o source_id do primeiro inbox associado.
sourceId = contatoEncontrado.contact_inboxes[0].source_id;
}

}

// 4. Retorna o resultado.
return [{
json: {
contato_existe: contatoExiste,
source_id: sourceId,
contact_id: contactId
}
}];

// --- CÓDIGO CORRIGIDO PARA FORMATAR CARRINHO COM ÍNDICE + ITENS INTERNOS ---

// 1. Pega os dados de entrada
const sessao = $items("confirma endereço")[0].json;
const pedido = $json.numero_pedido_formatado;

// 2. Valores numéricos
const valor_pedido_num = parseFloat(sessao.valor_pedido) || 0;
const desconto_aplicado_num = parseFloat(sessao.desconto_aplicado) || 0;
const valor_original_num = valor_pedido_num + desconto_aplicado_num;

// 3. Formatação moeda
const valor_pedido_formatado =
  valor_pedido_num.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const desconto_aplicado_formatado =
  desconto_aplicado_num.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const valor_original_formatado =
  valor_original_num.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});

// 4. Carrinho seguro
let carrinhoArray = [];
if (Array.isArray(sessao.carrinho_json)) {
  carrinhoArray = sessao.carrinho_json;
} else if (typeof sessao.carrinho_json === 'string') {
  try { carrinhoArray = JSON.parse(sessao.carrinho_json); }
  catch { carrinhoArray = []; }
}

// 5. Mapa seguro
let mapaObjeto = {};
if (typeof sessao.mapa_id_json === 'object' && sessao.mapa_id_json !== null) {
  mapaObjeto = sessao.mapa_id_json;
} else if (typeof sessao.mapa_id_json === 'string') {
  try { mapaObjeto = JSON.parse(sessao.mapa_id_json); }
  catch { mapaObjeto = {}; }
}

// 6. Variáveis
let totalGeral = 0;
let carrinhoTexto = "";
// 🔥 NOVO: Variável para contar as trufas individuais para a promoção
let qtdTrufas = 0; 

// 7. Loop carrinho
for (const itemNoCarrinho of carrinhoArray) {

  const subtotal =
    (itemNoCarrinho.qtd || 0) *
    (itemNoCarrinho.precoUnitario || 0);

  totalGeral += subtotal;

  // 🔥 NOVO: Conta a quantidade de trufas (ignorando combos)
  if (!itemNoCarrinho.nome?.toLowerCase().includes('combo')) {
    qtdTrufas += (itemNoCarrinho.qtd || 0);
  }

  const precoUnitarioFormatado =
    (itemNoCarrinho.precoUnitario || 0)
      .toLocaleString('pt-BR',{style:'currency',currency:'BRL'});

  const subtotalFormatado =
    subtotal.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});

  const indice = itemNoCarrinho.indice || "?";

  // --- ITEM PRINCIPAL ---
  carrinhoTexto += `*${indice})* `;
  if (itemNoCarrinho.nome?.toLowerCase().includes('combo')) {
    carrinhoTexto += `📦 ${itemNoCarrinho.nome.trim()}\n\n`;
  } else {
    carrinhoTexto += `🍫 ${itemNoCarrinho.nome.trim()}\n\n`;
  }

  carrinhoTexto += `*Quantidade:* ${itemNoCarrinho.qtd}\n`;
  carrinhoTexto += `*Preço:* ${precoUnitarioFormatado} *(${subtotalFormatado})*\n\n`;

  // =====================================================
  // 🔥 NOVO: ITENS INTERNOS DO COMBO
  // =====================================================
  if (Array.isArray(itemNoCarrinho.itens_internos)) {

    carrinhoTexto += `*Itens do combo:*\n`;

    const agrupados = {};

    for (const interno of itemNoCarrinho.itens_internos) {
      if (!agrupados[interno.nome]) agrupados[interno.nome] = 0;
      agrupados[interno.nome]++;
    }

    for (const nome in agrupados) {
      carrinhoTexto += `▫️ ${agrupados[nome]}x ${nome}\n`;
    }

    carrinhoTexto += "\n";
  }

  carrinhoTexto +=
    `--------------------------------------------------------\n\n`;
} // <-- A CHAVE DO LOOP QUE ESTAVA FALTANDO!

// 8. Resumo pedido
let resumo = carrinhoTexto;

if (desconto_aplicado_num > 0) {
  resumo += `💸→ DESCONTO:\n`;
  resumo += `*${desconto_aplicado_formatado}*\n\n`;
}

resumo += `🪙→ VALOR PEDIDO:\n`;

if (desconto_aplicado_num > 0) {
  resumo +=
    `~${valor_original_formatado}~ *${valor_pedido_formatado}*\n\n`;
} else {
  resumo += `*${valor_pedido_formatado}*\n`;
}

// 9. Chatwoot

let resumochatwoot = `🛍️→ PEDIDO: *${pedido}*`;
resumochatwoot += `\n\n----------------------------------------------------------\n\n`;
resumochatwoot += resumo;
resumochatwoot +=
`\n--------------------------------------------------------\n\n
*📍→ RUA/Nº:*\n\n${sessao.endereco}\n\n
*📍→ BAIRRO:*\n\n${sessao.bairro}\n\n
*📍→ CEP:*\n\n${sessao.cep.slice(0,5)+'-'+sessao.cep.slice(5)}\n\n
*📍→ COMPLEMENTO:*\n\n${sessao.complemento}\n\u200B`;

// =====================================================
// 🔥 NOVO: ALERTA DE UPSELL PARA O CHATWOOT
// =====================================================
if (qtdTrufas >= 2) {
  resumochatwoot += `\n\n🚨 *PROMO DESBLOQUEADA:* \nEste cliente tem ${qtdTrufas} trufas. Lembre-se de oferecer a promoção da Trufa de Doce de Leite por R$ 4,99 usando o atalho /promo!`;
}

// 10. Output
$json.resumo = resumo;
$json.resumochatwoot = resumochatwoot;
$json.Jid = sessao.Jid;
$json.telefone_real = sessao.telefone_real;

return $json;

